export interface QuizQuestion {
  id: string;
  stem: string;
  options: string[];
  correctIndex: number;
  explanation: string;
  distractorTip: string;
}

export interface UnitQuestLevel {
  id: number; // Unique numeric id, e.g. 101 for Unit 1 Level 1, 201 for Unit 2 Level 1
  unitIndex: number; // 1 to 8
  levelNumber: number; // 1 to N within unit
  uniqueKey: string; // e.g. "u1-l1", "u2-l1"
  topicNumber: string;
  name: string;
  subtitle: string;
  difficulty: 'Easy' | 'Medium' | 'Hard' | 'Boss';
  rewardCoins: number;
  questions: QuizQuestion[];
}

export interface UnitBiomeTheme {
  name: string;
  icon: string;
  accentColor: string;
  secondaryColor: string;
  groundGradient: string;
  cardBorder: string;
  trailColor: string;
  nodeRing: string;
  skyTint: string;
}

export interface UnitDefinition {
  unitIndex: number; // 1-indexed
  unitId: string;
  title: string;
  shortTitle: string;
  description: string;
  examWeight: string;
  biome: UnitBiomeTheme;
  levels: UnitQuestLevel[];
}

